{
  "narratives": [
    {
      "item_code": "S4_EYE",
      "title_raw": "가. 눈에 들어갔을 때",
      "start": "p3:L5",
      "end": "p3:L7"
    },
    {
      "item_code": "S4_SKIN",
      "title_raw": "나. 피부에 접촉했을 때",
      "start": "p3:L8",
      "end": "p3:L16"
    },
    {
      "item_code": "S4_INHAL",
      "title_raw": "다. 흡입했을 때",
      "start": "p3:L17",
      "end": "p3:L24"
    },
    {
      "item_code": "S4_INGEST",
      "title_raw": "라. 먹었을 때",
      "start": "p3:L25",
      "end": "p3:L27"
    },
    {
      "item_code": "S4_DOCTOR",
      "title_raw": "마. 기타 의사의 주의사항",
      "start": "p3:L28",
      "end": "p3:L30"
    }
  ],
  "extras": [
    {
      "after_item": "S4_EYE",
      "title_raw": "가. 눈에 들어갔을 때",
      "reason": "필드없음",
      "statements": [
        {
          "value": "- 물질과 접촉시 즉시 20분 이상 흐르는 물에 피부와 눈을 씻어내시오.",
          "line": "p3:L6"
        },
        {
          "value": "- 긴급 의료조치를 받으시오.",
          "line": "p3:L7"
        }
      ],
      "line": "p3:L6"
    },
    {
      "after_item": "S4_SKIN",
      "title_raw": "나. 피부에 접촉했을 때",
      "reason": "필드없음",
      "statements": [
        {
          "value": "- 뜨거운 물질인 경우, 열을 없애기 위해 영향을 받은 부위를 다량의 차가운 물에 담그거나 씻어내시오.",
          "line": "p3:L9"
        },
        {
          "value": "- 오염된 옷과 신발을 제거하고 격리하시오.",
          "line": "p3:L10"
        },
        {
          "value": "- 물질과 접촉시 즉시 20분 이상 흐르는 물에 피부와 눈을 씻어내시오.",
          "line": "p3:L11"
        },
        {
          "value": "- 경미한 피부 접촉 시 오염부위 확산을 방지하시오.",
          "line": "p3:L12"
        },
        {
          "value": "- 화상을 입은 경우에는 즉시 차가운 물로 해당 피부를 최대한 오랫동안 식히십시오. 피부에 달라붙은 옷은 제거하지 마십시오.",
          "line": "p3:L13"
        },
        {
          "value": "- 화상의 경우 즉시 찬물로 가능한 오래 해당부위를 식히고, 피부에 들러붙은 옷은 제거하지 마시오.",
          "line": "p3:L14"
        },
        {
          "value": "- 액화가스에 접촉한 경우 미지근한 물로 해당 부위를 녹이시오.",
          "line": "p3:L15"
        },
        {
          "value": "- 가스 또는 액화 가스와 접촉 시 화상, 심각한 상해, 동상을 유발할 수 있음.",
          "line": "p3:L16"
        }
      ],
      "line": "p3:L9"
    },
    {
      "after_item": "S4_INHAL",
      "title_raw": "다. 흡입했을 때",
      "reason": "필드없음",
      "statements": [
        {
          "value": "- 긴급 의료조치를 받으시오.",
          "line": "p3:L18"
        },
        {
          "value": "- 신선한 공기가 있는 곳으로 옮기시오.",
          "line": "p3:L19"
        },
        {
          "value": "- 호흡하지 않는 경우 인공호흡을 실시하시오.",
          "line": "p3:L20"
        },
        {
          "value": "- 물질을 먹거나 흡입하였을 경우 구강대구강법으로 인공호흡을 하지 말고 적절한 호흡의료장비를 이용하시오.",
          "line": "p3:L21"
        },
        {
          "value": "- 호흡이 힘들 경우 산소를 공급하시오.",
          "line": "p3:L22"
        },
        {
          "value": "- 따뜻하게 하고 안정되게 해주시오.",
          "line": "p3:L23"
        },
        {
          "value": "- 과량의 분진 또는 흄에 노출된 경우 깨끗한 공기로 제거하고 기침이나 다른 증상이 있을 경우 의료 조치를 취하시오.",
          "line": "p3:L24"
        }
      ],
      "line": "p3:L18"
    },
    {
      "after_item": "S4_INGEST",
      "title_raw": "라. 먹었을 때",
      "reason": "필드없음",
      "statements": [
        {
          "value": "- 즉시 의료조치를 취하시오.",
          "line": "p3:L26"
        },
        {
          "value": "- 물질을 먹거나 흡입하였을 경우 구강대구강법으로 인공호흡을 하지 말고 적절한 호흡의료장비를 이용하시오.",
          "line": "p3:L27"
        }
      ],
      "line": "p3:L26"
    },
    {
      "after_item": "S4_DOCTOR",
      "title_raw": "마. 기타 의사의 주의사항",
      "reason": "필드없음",
      "statements": [
        {
          "value": "- 의료인력이 해당물질에 대해 인지하고 보호조치를 취하도록 하시오.",
          "line": "p3:L29"
        },
        {
          "value": "- 폭로시 의료진에게 연락하고 추적조사 등의 특별한 응급조치를 취하시오.",
          "line": "p3:L30"
        }
      ],
      "line": "p3:L29"
    }
  ]
}

